"use server";

/**
 * Marks one notification read.
 *
 * Owner D. `notification:read` is granted to every role, but the resource
 * carries `recipientId` — the ownership escalation inside `can()` is what stops
 * one member marking another member's inbox.
 *
 * Must call (do not reimplement): markNotificationReadSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  markNotificationReadSchema,
  type MarkNotificationReadInput,
} from "@/schemas/notification";
import { markRead } from "@/server/services/notification-service";
import type { ActionResult } from "@/types/api";
import type { Notification } from "@/types/notification";

const run = withAction<typeof markNotificationReadSchema, Notification>(
  markNotificationReadSchema,
  async (raw, actor) => {
    const input = raw as MarkNotificationReadInput;

    const allowed = can(actor, "notification:read", {
      kind: "notification",
      orgId: input.orgId,
      recipientId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("notification:read");
    }

    const notification = await markRead(actor, input);
    revalidateTagged(["notifications"], CACHE_PROFILES.seconds);
    return notification;
  },
  { revalidate: ["notifications"], cacheProfile: "seconds" },
);

export async function markNotificationReadAction(
  raw: unknown,
): Promise<ActionResult<Notification>> {
  return run(raw);
}
"use server";

/**
 * Marks the whole inbox read.
 *
 * Owner D. Returns the number of rows touched so the bell badge can be updated
 * without a second round trip.
 *
 * Must call (do not reimplement): markAllNotificationsReadSchema, can,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { markAllNotificationsReadSchema } from "@/schemas/notification";
import { markAllRead } from "@/server/services/notification-service";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";

type MarkAllReadInput = { orgId: OrgId };

const run = withAction<typeof markAllNotificationsReadSchema, number>(
  markAllNotificationsReadSchema,
  async (raw, actor) => {
    const input = raw as MarkAllReadInput;

    const allowed = can(actor, "notification:manage", {
      kind: "notification",
      orgId: input.orgId,
      recipientId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("notification:manage");
    }

    const count = await markAllRead(actor, input.orgId);
    revalidateTagged(["notifications"], CACHE_PROFILES.seconds);
    return count;
  },
  { revalidate: ["notifications"], cacheProfile: "seconds" },
);

export async function markAllNotificationsReadAction(
  raw: unknown,
): Promise<ActionResult<number>> {
  return run(raw);
}
"use server";

/**
 * Updates one notification preference row.
 *
 * Owner D. `digestOnly` is only meaningful while the `digest_email` flag is on
 * for the organization; asking for it otherwise would strand the notification
 * in a digest that never gets sent, so the flag is checked here.
 *
 * Must call (do not reimplement): updateNotificationPreferenceSchema,
 * isEnabled, getActor, toActionResult
 */

import { FeatureUnavailableError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import {
  updateNotificationPreferenceSchema,
  type UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { updatePreference } from "@/server/services/notification-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { NotificationPreference } from "@/types/notification";

const run = withAction<
  typeof updateNotificationPreferenceSchema,
  NotificationPreference
>(
  updateNotificationPreferenceSchema,
  async (raw, actor) => {
    const input = raw as UpdateNotificationPreferenceInput;

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    const context = buildFlagContext(actor, organization);

    if (input.digestOnly && !isEnabled("digest_email", context)) {
      throw new FeatureUnavailableError("digest_email");
    }

    const preference = await updatePreference(actor, input);
    revalidateTagged(["notification-preferences"], CACHE_PROFILES.hours);
    return preference;
  },
  { revalidate: ["notification-preferences"], cacheProfile: "hours" },
);

export async function updateNotificationPreferenceAction(
  raw: unknown,
): Promise<ActionResult<NotificationPreference>> {
  return run(raw);
}
/**
 * Notification panel rendered into the `@panel` slot.
 *
 * Owner D. Matches `/[orgSlug]/notifications`, so opening notifications keeps
 * whatever page is already in the main column instead of navigating away from
 * it — the reason this slot exists at all.
 */

import Link from "next/link";
import { can } from "@/lib/permissions";
import { listNotifications } from "@/server/services/notification-service";
import { loadTenantContext } from "../../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

const PANEL_NOTIFICATION_LIMIT = 20;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "notification:read", {
    kind: "notification",
    orgId: org.id,
    recipientId: actor.userId,
  });
  if (!allowed) {
    return null;
  }

  const page = await listNotifications(actor, {
    orgId: org.id,
    recipientId: actor.userId,
    unreadOnly: search.unread === "1",
    limit: PANEL_NOTIFICATION_LIMIT,
  });

  return (
    <section className="p-6">
      <div className="flex items-baseline justify-between">
        <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
          Notifications
        </h2>
        <Link href={`/${orgSlug}/inbox`} className="text-xs text-indigo-600">
          Open inbox
        </Link>
      </div>

      <ul className="mt-4 space-y-3">
        {page.items.map((notification) => (
          <li key={notification.id}>
            <Link href={notification.href} className="block text-sm">
              <span
                className={
                  notification.readAt === null
                    ? "font-medium text-slate-900"
                    : "text-slate-600"
                }
              >
                {notification.title}
              </span>
              <span className="mt-0.5 block text-xs text-slate-500">
                {notification.body}
              </span>
            </Link>
          </li>
        ))}
      </ul>
    </section>
  );
}
/**
 * Daily digest built by the digest job from a `DigestBundle`. Entries are
 * capped at `DIGEST_MAX_ENTRIES` so one noisy day cannot produce an
 * unbounded email.
 */
import { Link, Section, Text } from "@react-email/components";
import type { ReactElement } from "react";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import { formatRelative } from "@/lib/date";
import type { DigestEntry } from "@/types/notification";
import { EmailButton } from "./_components/email-button";
import { EmailLayout } from "./_components/email-layout";

export type DigestEmailProps = {
  recipientName: string;
  orgName: string;
  entries: readonly DigestEntry[];
  inboxUrl: string;
};

const styles = {
  paragraph: { color: "#374151", fontSize: "15px", lineHeight: "24px" },
  entry: { borderTop: "1px solid #f3f4f6", padding: "10px 0" },
  entryTitle: { color: "#111827", fontSize: "14px", margin: 0 },
  entryMeta: { color: "#6b7280", fontSize: "12px", margin: "2px 0 0" },
  link: { color: "#6366f1", textDecoration: "none" },
  muted: { color: "#6b7280", fontSize: "13px", lineHeight: "20px" },
};

export function DigestEmail(props: DigestEmailProps): ReactElement | null {
  const { recipientName, orgName, entries, inboxUrl } = props;
  const shown = entries.slice(0, DIGEST_MAX_ENTRIES);
  const overflow = entries.length - shown.length;

  return (
    <EmailLayout
      preview={`${entries.length} update${entries.length === 1 ? "" : "s"} in ${orgName}`}
      heading={`Your ${orgName} digest`}
    >
      <Text style={styles.paragraph}>
        {recipientName}, here is what happened since your last digest.
      </Text>

      {shown.map((entry) => (
        <Section key={entry.notificationId} style={styles.entry}>
          <Text style={styles.entryTitle}>
            <Link href={entry.href} style={styles.link}>
              {entry.title}
            </Link>
          </Text>
          <Text style={styles.entryMeta}>
            {entry.kind.replace(/_/g, " ")} · {formatRelative(entry.occurredAt)}
          </Text>
        </Section>
      ))}

      {overflow > 0 ? (
        <Text style={styles.muted}>
          {`…and ${overflow} more update${overflow === 1 ? "" : "s"}.`}
        </Text>
      ) : null}

      <EmailButton href={inboxUrl} label="Open your inbox" />
    </EmailLayout>
  );
}
/**
 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
 */
import { createLogger } from "@/lib/logger";

export type OutgoingEmail = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

export type RenderedEmail = { subject: string; html: string; text: string };

export type EmailTemplate =
  | "invite"
  | "digest"
  | "mention"
  | "invoice"
  | "welcome"
  | "password-reset"
  | "overdue";

const logger = createLogger("email-service");

/** Subject lines per template; the props fill in the bracketed parts. */
const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
  invite: "You have been invited to a Taskflow workspace",
  digest: "Your Taskflow digest",
  mention: "You were mentioned in Taskflow",
  invoice: "Your Taskflow invoice",
  welcome: "Welcome to Taskflow",
  "password-reset": "Reset your Taskflow password",
  overdue: "You have overdue issues",
};

/**
 * "Sends" a message. Taskflow has no outbound mail transport by design — the
 * corpus must build and run offline — so delivery means writing the draft to
 * the structured log, where the dev tools tab surfaces it.
 */
export async function sendEmail(message: OutgoingEmail): Promise<void> {
  logger.info("email.sent", {
    to: message.to,
    subject: message.subject,
    bytes: message.html.length,
  });
}

/**
 * Renders a template to both an HTML and a plain-text body. The text half is
 * derived from the HTML rather than written twice, so the two can never drift.
 */
export async function renderEmail(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): Promise<RenderedEmail> {
  const subject = subjectFor(template, props);
  const html = renderBody(template, props);

  return { subject, html, text: toPlainText(html) };
}

function subjectFor(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const base = SUBJECTS[template];
  const orgName = props.orgName;
  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
}

function renderBody(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const rows = Object.entries(props)
    .filter(([, value]) => value !== null && value !== undefined)
    .map(
      ([key, value]) =>
        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
    )
    .join("");

  return [
    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    `<table>${rows}</table>`,
    "</body></html>",
  ].join("");
}

function toPlainText(html: string): string {
  return html
    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
"use client";

/**
 * Inbox list with read/unread affordances.
 */
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { cn } from "@/lib/cn";
import { formatRelative } from "@/lib/date";
import type { NotificationId } from "@/types/common";
import type { Notification } from "@/types/notification";
import type { ReactElement } from "react";

export type NotificationListProps = {
  notifications: readonly Notification[];
  onMarkRead: (id: NotificationId) => void;
  onMarkAllRead: () => void;
};

/** Unread first, then newest first — the inbox ordering people expect. */
export function orderInbox(
  notifications: readonly Notification[],
): readonly Notification[] {
  return [...notifications].sort((a, b) => {
    const byRead = Number(a.readAt !== null) - Number(b.readAt !== null);
    if (byRead !== 0) return byRead;
    return b.createdAt.localeCompare(a.createdAt);
  });
}

export function NotificationList(
  props: NotificationListProps,
): ReactElement | null {
  const { notifications, onMarkRead, onMarkAllRead } = props;

  if (notifications.length === 0) {
    return (
      <EmptyState
        title="You are all caught up"
        description="Assignments, mentions and status changes land here."
      />
    );
  }

  const ordered = orderInbox(notifications);
  const unread = ordered.filter((n) => n.readAt === null).length;

  return (
    <section className="notification-list space-y-2">
      <div className="flex items-center justify-between">
        <span className="text-sm text-neutral-500">{unread} unread</span>
        <Button
          variant="ghost"
          size="sm"
          disabled={unread === 0}
          onClick={onMarkAllRead}
        >
          Mark all read
        </Button>
      </div>

      <ul className="divide-y">
        {ordered.map((notification) => (
          <li
            key={notification.id}
            className={cn(
              "flex items-start justify-between gap-3 py-2",
              notification.readAt === null && "bg-indigo-50/50",
            )}
          >
            <Link href={notification.href} className="min-w-0 flex-1">
              <span className="block text-sm font-medium">
                {notification.title}
              </span>
              <span className="block text-sm text-neutral-600">
                {notification.body}
              </span>
              <span className="block text-xs text-neutral-500">
                {formatRelative(notification.createdAt)}
              </span>
            </Link>

            {notification.readAt === null ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onMarkRead(notification.id)}
              >
                Mark read
              </Button>
            ) : null}
          </li>
        ))}
      </ul>
    </section>
  );
}

import { z } from "zod";

/**
 * Coercions for reading pagination out of `searchParams`. Remember that in
 * Next 16 `searchParams` is a Promise — `await` it before parsing.
 */
export const searchParamsPaginationSchema = z.object({
  page: z.coerce.number().int().min(1).catch(1),
  perPage: z.coerce.number().int().min(1).max(100).catch(25),
  cursor: z.string().optional(),
});

export const searchParamsSortSchema = z.object({
  sort: z.string().max(40).optional(),
  dir: z.enum(["asc", "desc"]).catch("desc"),
});

export function toOffset(page: number, perPage: number): number {
  return (page - 1) * perPage;
}

export type SearchParamsPagination = z.infer<
  typeof searchParamsPaginationSchema
>;
export type SearchParamsSort = z.infer<typeof searchParamsSortSchema>;
"use client";

/**
 * Page-number pagination control.
 *
 * Owner A — design system. The windowing arithmetic lives in
 * `./_lib/pagination-range` so it can be unit-tested without a DOM; this file
 * is the markup around it. `usePagination` in the hooks layer owns the state.
 */
import type { ReactElement } from "react";
import { cn } from "@/lib/cn";
import {
  buildPageRange,
  pageCount,
  rangeEnd,
  rangeStart,
} from "./_lib/pagination-range";
import { FOCUS_RING } from "./_lib/tokens";

export type PaginationProps = { page: number; perPage: number; total: number; onPageChange: (page: number) => void };

export function Pagination(props: PaginationProps): ReactElement | null {
  const { page, perPage, total, onPageChange } = props;

  const pages = pageCount(total, perPage);
  // One page of results needs no control at all — the summary line alone is
  // noise on a list that cannot be paged.
  if (pages <= 1) return null;

  const current = Math.min(Math.max(1, page), pages);
  const tokens = buildPageRange(current, pages);

  const go = (target: number) => {
    const next = Math.min(Math.max(1, target), pages);
    if (next !== current) onPageChange(next);
  };

  const stepClass = cn(
    "inline-flex h-8 items-center rounded-md border border-black/12 px-2.5 text-xs text-black/70",
    "hover:bg-surface-muted disabled:cursor-not-allowed disabled:opacity-45",
    FOCUS_RING,
  );

  return (
    <nav
      aria-label="Pagination"
      className="flex flex-wrap items-center justify-between gap-3"
    >
      <p className="text-xs text-black/55 dark:text-white/55">
        <span className="tabular-nums">{rangeStart(current, perPage, total)}</span>
        {"–"}
        <span className="tabular-nums">{rangeEnd(current, perPage, total)}</span>
        {" of "}
        <span className="tabular-nums">{total}</span>
      </p>

      <div className="flex items-center gap-1">
        <button
          type="button"
          onClick={() => go(current - 1)}
          disabled={current === 1}
          className={stepClass}
        >
          Previous
        </button>

        {tokens.map((token, index) =>
          token === "gap" ? (
            <span
              key={`gap-${index}`}
              aria-hidden="true"
              className="px-1 text-xs text-black/40"
            >
              …
            </span>
          ) : (
            <button
              key={token}
              type="button"
              aria-label={`Page ${token}`}
              aria-current={token === current ? "page" : undefined}
              onClick={() => go(token)}
              className={cn(
                "inline-flex h-8 min-w-8 items-center justify-center rounded-md px-2 text-xs tabular-nums",
                token === current
                  ? "bg-brand-500 font-medium text-white"
                  : "text-black/70 hover:bg-surface-muted dark:text-white/70",
                FOCUS_RING,
              )}
            >
              {token}
            </button>
          ),
        )}

        <button
          type="button"
          onClick={() => go(current + 1)}
          disabled={current === pages}
          className={stepClass}
        >
          Next
        </button>
      </div>
    </nav>
  );
}
/**
 * Data-layer entry point. Repositories import `{ getDb }` and the table
 * objects from here so the concrete client module stays swappable.
 */
export { getDb, useInMemoryDb } from "./client";
export type { Db, DbSchema } from "./client";
export * from "./schema";
/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as usageRepo from "@/server/repositories/usage-repository";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  return usageRepo.recomputeUsage(orgId);
}

